/** Whose work Forecast shows: everyone's, your own, nobody's yet, or one person's ("person:Sam Patel"). */
export type ForecastWhose = 'everyone' | 'mine' | 'nobody' | `person:${string}`

export interface ForecastQuery {
  /** Default everyone. Staff always see their own clients, so this is theirs to narrow no further. */
  whose?: ForecastWhose
  /** Months ahead, this month included: 3, 6 or 12. Default 12. */
  months?: number
}

/** A calendar month: "2026-11", and how it reads ("Nov 2026"). */
export interface ForecastMonth {
  key: string
  label: string
}

/** Deadlines, tasks and work in progress over the months ahead. Arrays follow Forecast.months. */
export interface ForecastWorkload {
  /** Open deadlines already past their due date. */
  overdue: number
  /** How late the oldest of them is, in days (0 when none). */
  oldestOverdueDays: number
  /** Deadlines falling due in each month. */
  byMonth: number[]
  /** The same, by kind of work: the most first. */
  byObligation: Array<{ obligation: ObligationType; label: string; overdue: number; byMonth: number[]; total: number }>
  /** The same, by person: the busiest first; person null is nobody yet (always last). */
  byPerson: Array<{ person: string | null; overdue: number; byMonth: number[]; total: number }>
  /** The month with the most deadlines; null when none fall due. */
  busiest: { key: string; label: string; count: number } | null
  /** Open tasks: overdue, due in each month, and with no due date. */
  tasks: { overdue: number; byMonth: number[]; undated: number }
  /** Open work in progress, by person: open jobs, late ones, and those due this month. */
  wip: Array<{ person: string | null; open: number; late: number; dueThisMonth: number }>
}

/** Fees the practice expects to bill, from the fees recorded on services and clients. */
export interface ForecastFees {
  /** Recurring fees a year. */
  annualPence: number
  /** Expected billing in each month, recurring and one-off. */
  byMonth: number[]
  /** One-off fees dated within the months shown (included in byMonth). */
  oneOffPence: number
  /** Live clients with a fee recorded, and without one. */
  clientsWithFees: number
  clientsWithout: number
  /** Services with a fee but no regular frequency ("As needed", or none): not forecast. */
  unscheduledServices: number
  /** Recurring fees with no next date: spread evenly over the year. */
  spreadEvenly: number
}

/** Money owed to the practice and coming in: the same figures as Billing. */
export interface ForecastCash {
  owedPence: number
  overduePence: number
  creditPence: number
  /** Still owed on invoices, by the month each falls due (overdue ones are in overduePence). */
  expectedByMonth: number[]
  /** Owed on invoices with no due date. */
  undatedPence: number
  /** Received in each of the months before this one and this one, oldest first. */
  received: Array<{ key: string; label: string; pence: number }>
  /** Invoices on record, of any status. */
  invoices: number
}

export interface Forecast {
  today: string
  /** Staff: their own clients. */
  scope: 'practice' | 'own'
  whose: ForecastWhose
  months: ForecastMonth[]
  workload: ForecastWorkload
  fees: ForecastFees
  cash: ForecastCash
  /** Whose work can be shown (partners and managers): people with work, and people who sign in. */
  people: string[]
  /** Gaps in the records that limit the forecast, each with what to do. */
  notes: string[]
}

/** One sign-in event, from the audit log. */
export interface SignInEvent {
  id: number
  /** SQLite UTC. */
  at: string
  kind: 'signed_in' | 'failed' | 'refused' | 'signed_out' | 'idle_sign_out' | 'password_changed' | 'password_reset' | 'unlocked' | 'joined' | 'first_partner' | 'password_check_failed'
  /** Whose account; null when the name typed matched nobody. */
  person: string | null
  /** For a refused sign-in: the name that was typed. */
  attempted: string | null
  /** Who did it, when that was someone else (a partner resetting a password). */
  by: string | null
  /** The event in words. */
  text: string
}

export interface SignInQuery {
  /** How far back: 1 to 400 days. Default 30. */
  days?: number
  /** Only failures (wrong passwords, unknown names). */
  failedOnly?: boolean
  /** One person's events (partners and managers). */
  person?: string
  /** Default 200, at most 1000. */
  limit?: number
}

/** One entry in the audit log, for the security centre. */
export interface AuditEntry {
  id: number
  /** SQLite UTC. */
  at: string
  /** Who did it; "system" is the app itself. */
  who: string | null
  action: string
  table: string | null
  kind: PulseKind
  recordId: string | null
  clientRef: string | null
  clientName: string | null
  /** The fields that changed, when the entry records before and after. */
  changed: string[]
  /** What was recorded before and after (JSON), shortened past 20,000 characters. */
  before: string | null
  after: string | null
}

export interface AuditQuery {
  /** First and last day, YYYY-MM-DD on this computer's calendar. */
  from?: string
  to?: string
  /** One person's actions; "system" for the app's own. */
  who?: string
  kind?: PulseKind
  /** Words in the action, the record or the values. */
  find?: string
  /** The next page: entries older than this one. */
  beforeId?: number
  /** Default 100, at most 500. */
  limit?: number
}

export interface AuditPage {
  entries: AuditEntry[]
  /** Pass as beforeId for the next page; null at the end. */
  nextBeforeId: number | null
  /** Everyone who appears in the log, for the "Who" choice. */
  people: string[]
}

/** The result of checking the audit log against its seals. */
export interface AuditCheck {
  /** intact: every seal matches. changed: entries changed or removed since sealed. unsealed: nothing sealed yet. */
  state: 'intact' | 'changed' | 'unsealed'
  checkedAt: string
  /** Entries in the log now. */
  entries: number
  seals: number
  /** The last entry the latest seal covers, and when it was sealed (SQLite UTC). */
  sealedThrough: number | null
  sealedAt: string | null
  /** The start of the latest seal's value ("a1b2 c3d4 e5f6 a7b8"), to keep somewhere else and compare later. */
  fingerprint: string | null
  /** Entries added since the latest seal; they are sealed within the hour. */
  unsealed: number
  /** The first sealed stretch that no longer matches, and how many of its entries are missing. */
  problem: { fromId: number; toId: number; sealedAt: string; missing: number } | null
}

/** The security centre at a glance. Sections staff don't see are null. */
export interface SecurityOverview {
  database: PulseHealth['database']
  licence: PulseHealth['licence']
  /** Partners and managers. */
  backups: PulseHealth['backups']
  /** The encryption key's recovery sheet: partners. */
  recovery: RecoveryStatus | null
  /** Partners and managers. */
  vault: {
    setUp: boolean
    unlocked: boolean
    locksAt: string | null
    logins: number
    /** Flags to follow up, never errors: logins with no user ID, and with no password stored. */
    noUserId: number
    noPassword: number
    governmentSignIn: boolean
  } | null
  /** Partners and managers. */
  people: {
    total: number
    partners: number
    managers: number
    staff: number
    accessOff: number
    locked: number
    temporaryPasswords: number
    noPassword: number
    invites: number
  } | null
  signIns: { last30Days: number; failed30Days: number; lastFailedAt: string | null }
  /** Partners and managers. */
  audit: AuditCheck | null
  /** Minutes without use before the app signs out; 0 = never. */
  idleMinutes: number
  /** You: your last sign-in before this one, and failed attempts on your account in 30 days. */
  you: { lastSignIn: string | null; failed30Days: number }
}

